SELECT (DATE_TRUNC('DAY', "REFRESH_START_AT")) AS "TIME_BUCKET", SUM(CASE WHEN REFRESH_STATE <> 'SUCCEEDED' THEN 1 ELSE 0 END) AS "PIPE_DT_REFRESH_FAILURES" FROM (SELECT "QUALIFIED_NAME" AS QUALIFIED_NAME, "NAME" AS DYNAMIC_TABLE_NAME, "DATABASE_NAME" AS DATABASE_NAME, "SCHEMA_NAME" AS SCHEMA_NAME, "STATE" AS REFRESH_STATE, "STATE_MESSAGE" AS STATE_MESSAGE, "REFRESH_ACTION" AS REFRESH_ACTION, "REFRESH_TRIGGER" AS REFRESH_TRIGGER, "TARGET_LAG_SEC" AS TARGET_LAG_SEC, (TRY_CAST("REFRESH_START_TIME" AS TIMESTAMP)) AS REFRESH_START_AT, (TRY_CAST("REFRESH_END_TIME" AS TIMESTAMP)) AS REFRESH_END_AT, (TRY_CAST("DATA_TIMESTAMP" AS TIMESTAMP)) AS DATA_TIMESTAMP_AT, (DATE_DIFF('SECOND', (TRY_CAST("DATA_TIMESTAMP" AS TIMESTAMP)), (TRY_CAST("REFRESH_START_TIME" AS TIMESTAMP)))) AS ACTUAL_LAG_SEC, (DATE_DIFF('SECOND', (TRY_CAST("REFRESH_START_TIME" AS TIMESTAMP)), (TRY_CAST("REFRESH_END_TIME" AS TIMESTAMP)))) AS REFRESH_DURATION_SEC, ("_ACCOUNT") AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). */ FROM dynamic_table_refresh_history) AS base GROUP BY (DATE_TRUNC('DAY', "REFRESH_START_AT")) ORDER BY "PIPE_DT_REFRESH_FAILURES" DESC, "TIME_BUCKET" LIMIT 100
